#!/usr/bin/env python3
"""Build the authored exhibition sample; never writes a user's session."""
from pathlib import Path
from file_layout import json_bytes, split_inline_session

BASE = Path(__file__).resolve().parents[1] / 'assets' / 'workbench' / 'example'

def art(kind):
    opening = '<svg viewBox="0 0 400 400" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="展覧会のための抽象ポスター">'
    if kind == 'color':
        return opening + '<rect width="400" height="400" fill="#edecde"/><path d="M0 0h213v400H0z" fill="#bfd1e0"/><path d="M213 0h187v400H213z" fill="#eecb3e"/><ellipse cx="211" cy="201" rx="119" ry="159" fill="#ee5b33"/><path d="M213 42c64 0 117 71 117 159s-53 159-117 159z" fill="#ae392f"/><path d="M0 276h128v124H0z" fill="#424d9f"/><circle cx="74" cy="70" r="26" fill="#f3f2e9"/><path d="M330 0h70v110h-70z" fill="#283744"/></svg>'
    if kind == 'light':
        return opening + '<rect width="400" height="400" fill="#293e51"/><path d="M40 0h49v400H40zM151 0h21v400h-21zM255 0h71v400h-71z" fill="#576f75"/><path d="m0 290 400-175v153L0 400z" fill="#d9ddaf"/><path d="m0 290 400-175v40L0 330z" fill="#f2efcd"/><path d="M89 0h62v400H89z" fill="#1d354b" opacity=".72"/><path d="M172 0h83v400h-83z" fill="#20384a" opacity=".3"/></svg>'
    return opening + '<rect width="400" height="400" fill="#eddad0"/><path d="M60 0v400M120 0v400M180 0v400M240 0v400M300 0v400M360 0v400" stroke="#a15d4d" stroke-width="24"/><path d="M0 60h400M0 120h400M0 180h400M0 240h400M0 300h400M0 360h400" stroke="#deaea0" stroke-width="26"/><path d="M60 40v40M180 40v40M300 40v40M120 100v40M240 100v40M360 100v40M60 160v40M180 160v40M300 160v40M120 220v40M240 220v40M360 220v40M60 280v40M180 280v40M300 280v40M120 340v40M240 340v40M360 340v40" stroke="#985a4c" stroke-width="24"/></svg>'

EVENTS = [
    dict(title='色と、かたちのあいだ',kind='絵画',area='蔵前',venue='アトリエ棟',time='10:00–18:00',price='1,200',date='9.5 — 9.27',description='重なる色、ほどける輪郭。日常のなかにある抽象を見つける。',art='color'),
    dict(title='光を集める部屋',kind='写真',area='清澄白河',venue='ギャラリー井戸',time='11:00–19:00',price='900',date='9.10 — 10.4',description='窓辺に移ろう光を、写真家3人のまなざしで。',art='light'),
    dict(title='余白を編む',kind='工芸',area='谷中',venue='白い家',time='10:00–17:00',price='800',date='9.1 — 9.23',description='糸と手仕事から生まれる、暮らしの小さなかたち。',art='weave'),
]
LOGO = '<a class="logo" href="#"><svg viewBox="0 0 26 26" fill="none" aria-hidden="true"><path d="M3 6c11 0 4 14 13 14 4 0 7-4 7-8" stroke="currentColor" stroke-width="2"/><circle cx="5" cy="6" r="3" fill="currentColor"/><circle cx="23" cy="8" r="2" fill="currentColor"/></svg>よりみち</a>'
SAVE = '<button class="save" aria-label="気になる展覧会を保存"><svg viewBox="0 0 18 22" fill="none" aria-hidden="true"><path d="M3 2h12v18l-6-4-6 4V2Z" stroke="currentColor" stroke-width="1.3"/></svg></button>'
FOOT = '<footer class="sample-footer">サンプル画面です。展覧会・会場は架空のものです。</footer>'

def build_a():
    e=EVENTS[0]
    rows=''.join(f'<article class="small-event"><div class="small-art">{art(x["art"])}</div><div><span class="event-meta">{x["area"]} / {x["kind"]}</span><h3>{x["title"]}</h3><p>{x["venue"]}　¥{x["price"]}</p><p class="event-hours">{x["time"]}</p></div>{SAVE}</article>' for x in EVENTS[1:])
    return f'<header class="site-header">{LOGO}<nav><a href="#exhibitions">展覧会を探す</a><a href="#saved">保存した展覧会 <span>3</span></a></nav><span class="mobile-header">東京</span></header><main class="gallery"><section class="intro"><div class="weekend">東京の週末　9月12日・13日</div><h1>アートに、<br>寄り道。</h1><p>いつもの街から、少しだけ先へ。<br>今週末に訪ねたい、小さな展覧会。</p><a class="intro-link" href="#exhibitions">今週の3つの展覧会 <span>↗</span></a></section><article class="feature" id="exhibitions"><div class="feature-art">{art(e["art"])}<span class="art-caption">色と、かたちのあいだ</span></div><div class="feature-info"><div><span class="event-meta">{e["area"]} / {e["kind"]}</span><h2>{e["title"]}</h2><p class="description">{e["description"]}</p><p class="event-detail">{e["venue"]}　{e["time"]}<br>{e["date"]}　¥{e["price"]}</p></div>{SAVE}</div></article><section class="more" aria-label="ほかの展覧会"><div class="more-heading">もう少し、寄り道。</div><div class="more-list">{rows}</div></section></main>{FOOT}'

def build_b():
    rows=''.join(f'<article class="list-event"><div class="event-art">{art(e["art"])}</div><div class="event-copy"><div class="event-meta">{e["area"]}<span>{e["kind"]}</span></div><h2>{e["title"]}</h2><p class="description">{e["description"]}</p><p class="venue">{e["venue"]}</p><div class="facts"><span>{e["time"]}</span><span>¥{e["price"]}</span></div></div>{SAVE}</article>' for e in EVENTS)
    return f'<header class="site-header">{LOGO}<nav><a class="current" href="#">見つける</a><a href="#saved">保存 <span>3</span></a></nav><button class="menu-button" aria-label="メニュー">☰</button></header><div class="planner"><aside class="sidebar"><h2>東京を歩く</h2><p>今週末に行ける展覧会</p><div class="mini-map"><svg viewBox="0 0 260 240" aria-label="東京のエリア概念図"><path d="M0 68h260M0 139h260M0 210h260M45 0v240M112 0v240M214 0v240" stroke="#dfe5e7" stroke-width="13" fill="none"/><path d="M179 0c-10 66 40 69 7 143-14 32 1 76 4 97" stroke="#d1e4e8" stroke-width="23" fill="none"/><path d="m69 44 75 53 3 96" stroke="#537b83" stroke-width="2" fill="none" stroke-dasharray="4 5"/><circle cx="69" cy="44" r="6" fill="#2d6973"/><circle cx="144" cy="97" r="6" fill="#2d6973"/><circle cx="147" cy="193" r="6" fill="#2d6973"/><g font-family="sans-serif" font-size="12" fill="#536a73"><text x="80" y="40">谷中</text><text x="92" y="87">蔵前</text><text x="76" y="213">清澄白河</text></g></svg></div><p class="map-note">エリアの位置関係を示す概念図</p><div class="side-note"><span>週末のひとこと</span><p>ひとつ見たら、街を歩く。<br>予定を詰めすぎない一日に。</p></div></aside><main class="list-main"><div class="page-heading"><div><span class="weekend">9月12日・13日</span><h1>今週末、どこへ行こう。</h1><p>東京の小さな展覧会を、ひとつずつ。</p></div><span class="weather">東京</span></div><div class="filters"><button class="filter active">すべて</button><button class="filter">絵画</button><button class="filter">写真</button><button class="filter">工芸</button><span>3件</span></div><section class="event-list">{rows}</section><div class="list-bottom"><span>気になる場所を保存して、週末の予定に。</span><button>保存した3件を見る</button></div></main></div>{FOOT}'

def build_c():
    cards=''.join(f'<article class="poster-event"><div class="poster-art">{art(e["art"])}<span class="poster-kind">{e["kind"]}</span>{SAVE}<span class="poster-date">{e["date"]}</span></div><div class="poster-copy"><span class="event-meta">{e["area"]} / {e["venue"]}</span><h2>{e["title"]}</h2><p class="description">{e["description"]}</p><div class="event-bottom"><span>{e["time"]}</span><span>¥{e["price"]}</span></div></div></article>' for e in EVENTS)
    return f'<header class="site-header">{LOGO}<nav><a href="#exhibitions">今週の展覧会</a><a href="#saved">保存 <span>3</span></a></nav></header><main><section class="cover"><div class="cover-top"><span>東京の週末ガイド</span><span>9月12日・13日</span></div><h1>予定のない日を、<br>好きな色に。</h1><div class="cover-bottom"><p>アートを見て、街を歩いて。<br>今週は、この3つの場所から。</p><span class="cover-flower" aria-hidden="true">✳</span></div></section><section class="poster-grid" id="exhibitions">{cards}</section><section class="end-note"><span>また、次の寄り道で。</span><a href="#saved">気になる展覧会を保存する</a></section></main>{FOOT}'

